def wordpiece(word):
    pieces, start = [], 0
    while start<len(word):
        for end in range(len(word),start,-1):
            token=('##' if start else '')+word[start:end]
            if token in ID:
                pieces.append(token)
                start=end
                break
        else:
            return ['[UNK]']
    return pieces
