import json
import pandas as pd

def parse(answer):
    try:
        d=json.loads(answer[answer.index('{'):answer.rindex('}')+1])
        t=d.get('topic')
        sent=d.get('sentiment')
        if t in TOPICS and sent in ('negative','positive'):
            return (sent,t,True)
    except (ValueError,AttributeError,TypeError):
        pass
    return (None,None,False)
